class Monitor:
    command: str
    """Shell command to run as a persistent background monitor. Each stdout line is delivered to
    the model as a <task_notification> event; the process runs for the session lifetime.
    ${CLAUDE_PLUGIN_ROOT}, ${CLAUDE_PLUGIN_DATA}, ${user_config.*}, and ${ENV_VAR} are
    substituted. Runs in the session cwd — prefix with `cd "${CLAUDE_PLUGIN_ROOT}" && ` if
    the script needs its own directory.
    """
    description: str
    """Short human-readable description of what is being monitored (shown in task panel and
    notification summary).
    """
    name: str
    """Identifier for this monitor, unique within the plugin. Used to dedupe so re-arming
    (plugin reload, repeat skill invoke) does not spawn duplicates.
    """
    when: Optional[str]
    """Arm trigger. "always" arms at session start and on plugin reload.
    "on-skill-invoke:<skill>" arms the first time that skill is dispatched (via Skill tool or
    slash command).
    """

    def __init__(self, command: str, description: str, name: str, when: Optional[str]) -> None:
        self.command = command
        self.description = description
        self.name = name
        self.when = when

    @staticmethod
    def from_dict(obj: Any) -> 'Monitor':
        assert isinstance(obj, dict)
        command = from_str(obj.get("command"))
        description = from_str(obj.get("description"))
        name = from_str(obj.get("name"))
        when = from_union([from_str, from_none], obj.get("when"))
        return Monitor(command, description, name, when)

    def to_dict(self) -> dict:
        result: dict = {}
        result["command"] = from_str(self.command)
        result["description"] = from_str(self.description)
        result["name"] = from_str(self.name)
        if self.when is not None:
            result["when"] = from_union([from_str, from_none], self.when)
        return result


