class DefaultMode(Enum):
    """Default permission mode.
    "default": prompts on first use.
    "acceptEdits": auto-accepts file edits.
    "plan": read-only, no modifications.
    UNDOCUMENTED. "delegate": coordination-only for agent team leads (agent teams are
    experimental; enable via CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS).
    "dontAsk": auto-denies unless pre-approved via permissions.
    "bypassPermissions": skips all prompts (use only in isolated environments).
    "auto": auto-approves tool calls with background safety checks that verify actions align
    with your request.
    See https://code.claude.com/docs/en/permissions
    """
    ACCEPT_EDITS = "acceptEdits"
    AUTO = "auto"
    BYPASS_PERMISSIONS = "bypassPermissions"
    DEFAULT = "default"
    DELEGATE = "delegate"
    DONT_ASK = "dontAsk"
    PLAN = "plan"


class Permissions:
    """Tool usage permissions configuration.
    See https://code.claude.com/docs/en/permissions and
    https://code.claude.com/docs/en/settings#permission-settings
    See https://code.claude.com/docs/en/tools-reference for full list of tools available to
    Claude.
    """
    additional_directories: Optional[List[str]]
    """Additional directories to include in the permission scope"""

    allow: Optional[List[str]]
    """List of permission rules for allowed operations"""

    ask: Optional[List[str]]
    """List of permission rules that should always prompt for confirmation"""

    default_mode: Optional[DefaultMode]
    """Default permission mode.
    "default": prompts on first use.
    "acceptEdits": auto-accepts file edits.
    "plan": read-only, no modifications.
    UNDOCUMENTED. "delegate": coordination-only for agent team leads (agent teams are
    experimental; enable via CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS).
    "dontAsk": auto-denies unless pre-approved via permissions.
    "bypassPermissions": skips all prompts (use only in isolated environments).
    "auto": auto-approves tool calls with background safety checks that verify actions align
    with your request.
    See https://code.claude.com/docs/en/permissions
    """
