class Sandbox:
    """Sandbox execution configuration. See https://code.claude.com/docs/en/sandboxing"""

    allow_unsandboxed_commands: Optional[bool]
    """Allow commands to run outside the sandbox via the dangerouslyDisableSandbox parameter.
    When false, the dangerouslyDisableSandbox parameter is completely ignored and all
    commands must run sandboxed. Default: true. See
    https://code.claude.com/docs/en/sandboxing#limitations
    """
    auto_allow_bash_if_sandboxed: Optional[bool]
    """Automatically allow bash commands without prompting when they run in the sandbox. Only
    applies to commands that will run sandboxed. See
    https://code.claude.com/docs/en/sandboxing#sandbox-modes
    """
    enabled: Optional[bool]
    """Enable sandboxed bash. See https://code.claude.com/docs/en/sandboxing#enable-sandboxing"""

    enable_weaker_nested_sandbox: Optional[bool]
    """Enable weaker sandbox mode for unprivileged docker environments where --proc mounting
    fails. This significantly reduces the strength of the sandbox and should only be used
    when this risk is acceptable. Default: false (secure). See
    https://code.claude.com/docs/en/sandboxing#limitations
    """
    enable_weaker_network_isolation: Optional[bool]
    """macOS only. Allow access to the system TLS trust service (com.apple.trustd.agent) in the
    sandbox. Required for Go-based tools like gh, gcloud, and terraform to verify TLS
    certificates when using httpProxyPort with a MITM proxy and custom CA. Reduces security
    by opening a potential data exfiltration path. Default: false. See
    https://code.claude.com/docs/en/settings#sandbox-settings
    """
    excluded_commands: Optional[List[str]]
    """Commands that should never run in the sandbox (e.g., ["git", "docker"]). See
    https://code.claude.com/docs/en/sandboxing#configure-sandboxing
    """
    filesystem: Optional[Filesystem]
    """Filesystem access control for sandboxed commands. See
    https://code.claude.com/docs/en/sandboxing#filesystem-isolation
    """
    ignore_violations: Optional[Dict[str, List[str]]]
    """Map of command patterns to filesystem paths to ignore violations for. Use "*" to match
    all commands
    """
    network: Optional[Network]
    """Configures network isolation settings for the sandboxed bash environment, including
    domain restrictions, Unix socket access, and custom proxy configuration.
    """
    ripgrep: Optional[Ripgrep]
    """Custom ripgrep configuration for Claude Code's bundled ripgrep support. Overrides the
    bundled binary and arguments.
    """

